import{_ as a,o as l,c as d,a5 as r}from"./chunks/framework.Bt0SrEfo.js";const b=JSON.parse('{"title":"双方向自动化求职计划书","description":"","frontmatter":{},"headers":[],"relativePath":"agent/auto/rpa.md","filePath":"agent/auto/rpa.md","lastUpdated":1792686342000}'),i={name:"agent/auto/rpa.md"};function e(o,t,n,h,s,p){return l(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="双方向自动化求职计划书" tabindex="-1">双方向自动化求职计划书 <a class="header-anchor" href="#双方向自动化求职计划书" aria-label="Permalink to &quot;双方向自动化求职计划书&quot;">​</a></h1><blockquote><p><strong>方向：跨境电商自动化 × 通用办公自动化</strong><br><strong>计划周期：</strong> 8 周　|　<strong>每日投入：</strong> 约 2 小时　|　<strong>目标：</strong> 兼顾短期就业与长期技术发展</p></blockquote><ul><li><strong>适用背景：</strong> 7 年前端开发经验，正在学习影刀 RPA 与 Python。</li><li><strong>核心策略：</strong> 一套共用技术底座、两个可演示项目、两条岗位投递线。</li><li><strong>执行原则：</strong> 第 1 周就开始投递，不等全部学完；根据真实招聘反馈调整投入。</li></ul><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ul><li><a href="#一计划摘要">一、计划摘要</a></li><li><a href="#二两条求职方向">二、两条求职方向</a></li><li><a href="#三共用技能底座">三、共用技能底座</a></li><li><a href="#四项目一通用办公自动化-excel-报表工具">四、项目一：通用办公自动化 Excel 报表工具</a></li><li><a href="#五项目二跨境电商订单对账与利润分析">五、项目二：跨境电商订单对账与利润分析</a></li><li><a href="#六-8-周学习计划">六、8 周学习计划</a></li><li><a href="#七每日-2-小时安排">七、每日 2 小时安排</a></li><li><a href="#八投递策略">八、投递策略</a></li><li><a href="#九面试准备清单">九、面试准备清单</a></li><li><a href="#十阶段检查点与风险控制">十、阶段检查点与风险控制</a></li><li><a href="#十一长期发展路线">十一、长期发展路线</a></li><li><a href="#附录每周复盘模板">附录：每周复盘模板</a></li></ul><h2 id="一、计划摘要" tabindex="-1">一、计划摘要 <a class="header-anchor" href="#一、计划摘要" aria-label="Permalink to &quot;一、计划摘要&quot;">​</a></h2><p>这不是从零开始转行。已有的前端开发经验可以迁移到业务流程拆解、接口联调、调试排错、模块化设计和系统集成。接下来需要补齐的是 <strong>Python 数据处理、RPA 流程编排、API 集成和业务自动化项目经验</strong>。</p><p>建议前期将精力按 <strong>通用办公自动化 60% / 跨境电商自动化 40%</strong> 分配。办公自动化场景更通用，适合作为先行求职方向；跨境电商项目则帮助形成更明确的业务特色。实际比例应根据岗位数量、面试反馈和个人兴趣调整。</p><table tabindex="0"><thead><tr><th>阶段</th><th>核心目标</th><th>阶段产出</th></tr></thead><tbody><tr><td>第 1–2 周</td><td>衔接基础、启动求职</td><td>影刀 + Python 小工具、简历初版</td></tr><tr><td>第 3–4 周</td><td>完成办公项目、启动跨境项目</td><td>Excel 报表工具、订单对账主流程</td></tr><tr><td>第 5–6 周</td><td>完成跨境项目、补齐 API 能力</td><td>利润分析报表、API 与日志示例</td></tr><tr><td>第 7–8 周</td><td>工程化、面试复盘、方向校准</td><td>两份定向简历、项目说明、投递复盘</td></tr></tbody></table><h2 id="二、两条求职方向" tabindex="-1">二、两条求职方向 <a class="header-anchor" href="#二、两条求职方向" aria-label="Permalink to &quot;二、两条求职方向&quot;">​</a></h2><h3 id="方向-a-通用办公自动化" tabindex="-1">方向 A：通用办公自动化 <a class="header-anchor" href="#方向-a-通用办公自动化" aria-label="Permalink to &quot;方向 A：通用办公自动化&quot;">​</a></h3><p><strong>主要服务对象：</strong> 行政、人事、财务、销售、采购和运营等团队。重点是减少重复的数据处理与流程操作。</p><p><strong>典型应用场景</strong></p><ul><li>多份 Excel / CSV 文件合并、清洗和格式统一。</li><li>自动生成日报、周报及部门汇总报表。</li><li>批量处理文件、网页录入和表单操作。</li><li>异常数据检查，以及邮件、飞书等通知流程。</li></ul><p><strong>可搜索的岗位关键词</strong></p><ul><li>办公自动化工程师</li><li>RPA 开发工程师 / RPA 实施工程师</li><li>Python 自动化开发</li><li>流程自动化工程师</li><li>数据处理自动化</li></ul><p><strong>简历重点：</strong> Excel / CSV 处理、影刀流程、Python 脚本集成、异常检测、日志和报表输出。</p><h3 id="方向-b-跨境电商自动化" tabindex="-1">方向 B：跨境电商自动化 <a class="header-anchor" href="#方向-b-跨境电商自动化" aria-label="Permalink to &quot;方向 B：跨境电商自动化&quot;">​</a></h3><p><strong>主要服务对象：</strong> 跨境电商运营团队。围绕订单、退款、SKU、库存、物流费用、销售和利润报表开展自动化。</p><p><strong>典型应用场景</strong></p><ul><li>订单对账、退款核对和异常订单识别。</li><li>SKU 成本关联、库存预警和销售汇总。</li><li>按明确规则生成模拟利润分析报表。</li><li>通过 ERP 或平台 API 同步业务数据。</li></ul><p><strong>可搜索的岗位关键词</strong></p><ul><li>跨境电商自动化工程师</li><li>运营自动化开发</li><li>Python 开发工程师</li><li>电商数据处理</li><li>RPA 自动化工程师</li><li>ERP 系统集成</li></ul><p><strong>简历重点：</strong> 订单关联、退款与成本核对、利润报表、Pandas、API 集成和异常追踪。</p><h3 id="个人定位建议" tabindex="-1">个人定位建议 <a class="header-anchor" href="#个人定位建议" aria-label="Permalink to &quot;个人定位建议&quot;">​</a></h3><blockquote><p>具备多年软件开发经验，正在向 Python 与 RPA 自动化开发拓展；擅长将业务需求拆解为可执行流程，通过脚本、数据处理和接口集成减少重复工作，并关注数据校验、异常处理和流程可维护性。</p></blockquote><p><strong>诚信原则：</strong> 练习项目应明确标注为“个人实践项目”，不虚构企业使用情况、上线规模或业务收益。面试时重点展示设计思路、可运行结果和验证过程。</p><h2 id="三、共用技能底座" tabindex="-1">三、共用技能底座 <a class="header-anchor" href="#三、共用技能底座" aria-label="Permalink to &quot;三、共用技能底座&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>学习重点</th><th>可验证能力</th></tr></thead><tbody><tr><td>影刀 RPA</td><td>变量、列表、循环、条件、Excel、网页操作、异常分支</td><td>完成稳定的端到端流程</td></tr><tr><td>Python</td><td>函数、路径、CSV / Excel 读写、异常处理、模块拆分</td><td>编写并维护自动化脚本</td></tr><tr><td>数据处理</td><td>pandas 合并、筛选、去重、汇总；openpyxl 多工作表输出</td><td>将原始数据转成可复核报表</td></tr><tr><td>API</td><td>HTTP、JSON、Token、分页、超时、重试</td><td>连接获准访问的业务接口</td></tr><tr><td>工程化</td><td>Git、日志、配置、数据校验、测试、重复运行保护</td><td>出错可排查，结果可追踪</td></tr><tr><td>业务表达</td><td>流程图、操作说明、异常清单、结果对比</td><td>能解释业务痛点与自动化价值</td></tr></tbody></table><p><strong>分工原则：</strong> 影刀负责流程编排，Python 负责复杂数据处理，API 负责系统间数据交换。对于稳定且获准使用的 API，应优先评估接口方案，不要把所有任务都做成网页模拟点击。</p><h2 id="四、项目一-通用办公自动化-excel-报表工具" tabindex="-1">四、项目一：通用办公自动化 Excel 报表工具 <a class="header-anchor" href="#四、项目一-通用办公自动化-excel-报表工具" aria-label="Permalink to &quot;四、项目一：通用办公自动化 Excel 报表工具&quot;">​</a></h2><p><strong>项目目标：</strong> 将多份格式不统一的 Excel / CSV 文件自动整理为标准报表，展示数据处理、异常识别和流程自动化能力。</p><h3 id="功能设计" tabindex="-1">功能设计 <a class="header-anchor" href="#功能设计" aria-label="Permalink to &quot;功能设计&quot;">​</a></h3><ol><li>准备至少 5 份模拟文件，包含字段差异、重复记录、空值、日期格式不统一和异常金额。</li><li>使用影刀获取文件列表并编排流程。</li><li>使用 Python + pandas 合并、清洗、去重和汇总数据。</li><li>使用 openpyxl 输出包含多个工作表的报表。</li><li>输出汇总报表、异常明细、处理日志、运行摘要和操作说明。</li></ol><h3 id="验收标准" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准" aria-label="Permalink to &quot;验收标准&quot;">​</a></h3><ul><li>异常数据不会被悄悄忽略，而是进入异常清单或日志。</li><li>重复运行不会无故重复追加数据。</li><li>处理结果可以追溯到原始文件和明细记录。</li><li>提供 README、流程图和测试样例。</li></ul><h3 id="建议目录结构" tabindex="-1">建议目录结构 <a class="header-anchor" href="#建议目录结构" aria-label="Permalink to &quot;建议目录结构&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>office-automation/</span></span>
<span class="line"><span>├── data/</span></span>
<span class="line"><span>│   ├── input/</span></span>
<span class="line"><span>│   └── output/</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>├── logs/</span></span>
<span class="line"><span>├── tests/</span></span>
<span class="line"><span>└── README.md</span></span></code></pre></div><h2 id="五、项目二-跨境电商订单对账与利润分析" tabindex="-1">五、项目二：跨境电商订单对账与利润分析 <a class="header-anchor" href="#五、项目二-跨境电商订单对账与利润分析" aria-label="Permalink to &quot;五、项目二：跨境电商订单对账与利润分析&quot;">​</a></h2><p><strong>项目目标：</strong> 模拟运营人员整理订单、退款、SKU 成本和物流费用的工作，重点展示多表关联、对账、异常定位和报表生成。</p><h3 id="功能设计-1" tabindex="-1">功能设计 <a class="header-anchor" href="#功能设计-1" aria-label="Permalink to &quot;功能设计&quot;">​</a></h3><ol><li>准备订单、退款、SKU 成本、物流费用等 CSV / Excel 模拟数据。</li><li>按订单号或 SKU 关联数据表，并明确关联规则。</li><li>识别重复订单、缺失成本、退款不匹配和其他异常记录。</li><li>按自行定义的模拟规则计算销售额、退款、商品成本、物流费及模拟平台费用。</li><li>输出对账结果、利润汇总、异常清单、运行日志和业务规则说明。</li></ol><h3 id="验收标准-1" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准-1" aria-label="Permalink to &quot;验收标准&quot;">​</a></h3><ul><li>至少覆盖 100 条模拟订单。</li><li>汇总结果可以追溯到订单明细。</li><li>相同输入重复运行时，结果保持一致。</li><li>费用和利润计算规则有明确说明，并通过样例核对。</li></ul><blockquote><p><strong>重要说明：</strong> 项目利润仅按模拟规则计算，不等于任何平台的实际结算利润。后续若接入真实业务，应先核实平台规则、币种、退款口径、物流费用和各类手续费。</p></blockquote><h2 id="六、8-周学习计划" tabindex="-1">六、8 周学习计划 <a class="header-anchor" href="#六、8-周学习计划" aria-label="Permalink to &quot;六、8 周学习计划&quot;">​</a></h2><table tabindex="0"><thead><tr><th>周次</th><th>学习主题</th><th>学习与实践任务</th><th>阶段交付物</th></tr></thead><tbody><tr><td>第 1 周</td><td>影刀 + Python 基础</td><td>学习变量、列表、循环、条件、Excel 操作；复习 Python 函数、路径和异常处理；完成 Excel 筛选并导出的小工具</td><td>可运行小工具、简历初版；开始投递</td></tr><tr><td>第 2 周</td><td>pandas / openpyxl</td><td>练习多文件合并、去重、字段统一、分组汇总和多工作表输出；构造办公模拟数据</td><td>办公项目 MVP</td></tr><tr><td>第 3 周</td><td>完善办公项目</td><td>增加数据校验、异常明细、日志、配置和重复运行保护；编写 README 与流程图</td><td>第一个完整可演示项目</td></tr><tr><td>第 4 周</td><td>跨境业务与对账</td><td>梳理 SKU、订单、退款、物流费和平台费用；完成数据关联、核对和异常识别</td><td>跨境项目主流程</td></tr><tr><td>第 5 周</td><td>利润分析与报表</td><td>按模拟规则计算销售额、退款、成本和费用；核对样例并准备项目讲解</td><td>第二个可演示项目</td></tr><tr><td>第 6 周</td><td>API 与 RPA 协作</td><td>学习 HTTP、JSON、Token、分页、超时和重试；练习影刀触发 Python 并读取结果</td><td>可重复运行的流程与日志</td></tr><tr><td>第 7 周</td><td>工程化与面试</td><td>学习基础 SQL、Git 和测试样例；完善异常日志；根据面试反馈补短板</td><td>整理后的代码、项目讲解稿</td></tr><tr><td>第 8 周</td><td>求职冲刺</td><td>复盘投递与面试；定制简历；练习项目演示、技术题和业务场景题</td><td>两份定向简历、求职复盘</td></tr></tbody></table><h2 id="七、每日-2-小时安排" tabindex="-1">七、每日 2 小时安排 <a class="header-anchor" href="#七、每日-2-小时安排" aria-label="Permalink to &quot;七、每日 2 小时安排&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时长</th><th>任务</th><th>执行要求</th></tr></thead><tbody><tr><td>20 分钟</td><td>学习知识点</td><td>只学当天项目需要的内容，避免漫无目的地看教程</td></tr><tr><td>70 分钟</td><td>编码或搭建影刀流程</td><td>以实际产出为主；先复现问题，再排查原因</td></tr><tr><td>20 分钟</td><td>测试与记录</td><td>记录输入、输出、异常和解决方法</td></tr><tr><td>10 分钟</td><td>投递或复盘</td><td>更新跟踪表、跟进招聘方、记录面试问题</td></tr></tbody></table><p>建议每周执行 6 天，另留 1 天休息或补进度。遇到面试时，优先准备面试。<strong>计划是提高就业概率的工具，不应成为推迟求职的理由。</strong></p><h2 id="八、投递策略" tabindex="-1">八、投递策略 <a class="header-anchor" href="#八、投递策略" aria-label="Permalink to &quot;八、投递策略&quot;">​</a></h2><h3 id="投递节奏" tabindex="-1">投递节奏 <a class="header-anchor" href="#投递节奏" aria-label="Permalink to &quot;投递节奏&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>建议节奏</th><th>重点</th></tr></thead><tbody><tr><td>第 1–2 周</td><td>每周 15–25 个匹配岗位</td><td>验证简历定位，分别记录两条方向的反馈</td></tr><tr><td>第 3–4 周</td><td>每周 20–30 个匹配岗位</td><td>优先投递与办公项目匹配的岗位，同时增加跨境岗位</td></tr><tr><td>第 5–8 周</td><td>根据反馈动态调整</td><td>定向修改简历、准备面试，不为凑数量投递明显不匹配的岗位</td></tr></tbody></table><p>以上数量是执行参考，不是招聘市场的统计规律。如果合适岗位较少，不必为了凑数而投递完全不符合的职位。</p><h3 id="两份简历分别突出什么" tabindex="-1">两份简历分别突出什么 <a class="header-anchor" href="#两份简历分别突出什么" aria-label="Permalink to &quot;两份简历分别突出什么&quot;">​</a></h3><p><strong>办公自动化版</strong></p><ul><li>Excel / CSV 处理</li><li>影刀流程设计与调试</li><li>Python 脚本集成</li><li>异常检测、日志和报表输出</li></ul><p><strong>跨境电商版</strong></p><ul><li>订单对账、退款核对</li><li>SKU 成本关联</li><li>利润分析报表</li><li>API 集成与异常追踪</li></ul><p>两份简历都保留真实的前端经历，重点突出接口联调、流程拆解、调试排错和模块化能力。个人项目应标注为练习或实践项目，不包装成商业交付经历。</p><h3 id="求职跟踪字段" tabindex="-1">求职跟踪字段 <a class="header-anchor" href="#求职跟踪字段" aria-label="Permalink to &quot;求职跟踪字段&quot;">​</a></h3><p>建议建立一张表，记录以下字段：</p><p><code>岗位名称｜公司｜方向｜薪资范围｜地点/工作形式｜关键要求｜投递日期｜回复状态｜面试阶段｜失败原因｜下一步行动</code></p><h3 id="根据反馈调整" tabindex="-1">根据反馈调整 <a class="header-anchor" href="#根据反馈调整" aria-label="Permalink to &quot;根据反馈调整&quot;">​</a></h3><ul><li><strong>投递多但没有回复：</strong> 检查岗位匹配度、简历标题，以及项目成果是否具体。</li><li><strong>技术面失分：</strong> 集中补 Python、pandas、API、异常处理和项目实现细节。</li><li><strong>业务面不通过：</strong> 练习解释原流程痛点、自动化方案、数据校验和失败恢复。</li></ul><h2 id="九、面试准备清单" tabindex="-1">九、面试准备清单 <a class="header-anchor" href="#九、面试准备清单" aria-label="Permalink to &quot;九、面试准备清单&quot;">​</a></h2><ul><li>[ ] <strong>Python：</strong> 列表 / 字典、函数、文件处理、异常处理、模块拆分。</li><li>[ ] <strong>pandas：</strong> 读取文件、merge、去重、缺失值处理、groupby、导出。</li><li>[ ] <strong>Excel：</strong> 多工作表、格式统一、公式 / 数值核验、异常数据标记。</li><li>[ ] <strong>RPA：</strong> 变量、循环、条件分支、网页元素定位、等待、异常分支、日志和重试。</li><li>[ ] <strong>API：</strong> HTTP 方法、状态码、JSON、认证、分页、超时、重试和幂等。</li><li>[ ] <strong>工程化：</strong> Git、配置文件、日志、测试数据、重复运行保护。</li><li>[ ] <strong>项目讲解：</strong> 业务痛点、流程图、输入输出、异常案例、结果校验和可扩展点。</li></ul><h2 id="十、阶段检查点与风险控制" tabindex="-1">十、阶段检查点与风险控制 <a class="header-anchor" href="#十、阶段检查点与风险控制" aria-label="Permalink to &quot;十、阶段检查点与风险控制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间点</th><th>目标状态</th><th>未达到时的调整</th></tr></thead><tbody><tr><td>第 2 周末</td><td>有一个能运行的小工具，并已开始投递</td><td>减少看教程的时间，优先完成最小可用功能</td></tr><tr><td>第 4 周末</td><td>办公项目可演示，跨境项目完成主流程</td><td>暂停扩展功能，先打通输入、处理、输出闭环</td></tr><tr><td>第 6 周末</td><td>两个项目可演示，具备基础 API 与日志能力</td><td>根据招聘反馈补齐缺口，不盲目学习次要框架</td></tr><tr><td>第 8 周末</td><td>两份定向简历、项目材料和投递数据齐全</td><td>根据回复率和面试进展重新分配精力</td></tr></tbody></table><p>如果现金流压力上升，应优先争取可接受的短期工作、合同制开发或临时项目机会，不要为了等待作品完美而推迟求职。对岗位的薪资、合同、试用期、实际工作内容和培训收费保持核实。</p><h2 id="十一、长期发展路线" tabindex="-1">十一、长期发展路线 <a class="header-anchor" href="#十一、长期发展路线" aria-label="Permalink to &quot;十一、长期发展路线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>能力目标</th><th>可探索的方向</th></tr></thead><tbody><tr><td>1. 自动化执行</td><td>用影刀完成明确流程，处理常见网页和 Excel 操作</td><td>RPA / 办公自动化入门岗位</td></tr><tr><td>2. 自动化开发</td><td>用 Python 处理数据、调用 API、处理异常并维护脚本</td><td>Python 自动化开发、运营自动化</td></tr><tr><td>3. 系统集成</td><td>连接数据库、ERP、业务 API 和消息通知，形成稳定工作流</td><td>业务系统集成、数据自动化开发</td></tr><tr><td>4. 智能化应用</td><td>在可靠的数据流程上增加 AI 分类、异常归因、报告生成或 Agent 能力</td><td>AI 应用开发、业务自动化平台</td></tr></tbody></table><p><strong>长期建议：</strong> 先把数据准确性、流程可靠性和业务闭环做好，再叠加 AI 能力。基础自动化尚未稳定前，不必过早投入复杂 Agent 框架。</p><h2 id="附录-每周复盘模板" tabindex="-1">附录：每周复盘模板 <a class="header-anchor" href="#附录-每周复盘模板" aria-label="Permalink to &quot;附录：每周复盘模板&quot;">​</a></h2><ul><li>[ ] 本周完成了什么可运行的功能？</li><li>[ ] 项目输入、输出和异常情况是否都验证过？</li><li>[ ] 本周分别投递了多少个办公自动化岗位、多少个跨境电商岗位？</li><li>[ ] 收到多少回复、面试或反馈？主要问题是什么？</li><li>[ ] 下周最重要的一个技术短板是什么？</li><li>[ ] 下周要交付的具体功能是什么？</li></ul>`,75)])])}const u=a(i,[["render",e]]);export{b as __pageData,u as default};
